"""Offline current-room check, separate from formal P0-P6 / A-H acceptance."""
import json,hashlib,sys
from pathlib import Path
run=Path(sys.argv[1]);root=Path(__file__).resolve().parents[1];load=lambda n:json.loads((run/n).read_text())
arrival=load('arrival-evaluation.json');clearance=load('crossing-evaluation.json');boot=load('px4-boot-parameters.json');contract=load('runtime-contract.json');isolation=load('px4-run-isolation.json');flight=load('flight.json')
changed=[name for name,digest in contract['files'].items() if hashlib.sha256((root/name).read_bytes()).hexdigest()!=digest]
source=Path(isolation['source_build']);assert source.is_relative_to('/workspace');source=root/source.relative_to('/workspace');source_changed=[name for name,digest in isolation['source_mutable_sha256'].items() if hashlib.sha256((source/name).read_bytes()).hexdigest()!=digest]
splines=[p['message'] for p in load('planner-observation.json')['messages'] if p['type']=='bspline']
last=splines[-1];tail=last['pos_pts'][-3:];goal=flight['goal']['target_enu']
endpoint=[sum(w*p[k] for w,p in zip([1/6,4/6,1/6],tail)) for k in ['x','y','z']]
terminal_error=sum((a-b)**2 for a,b in zip(endpoint,goal))**.5
terminal_flat=max(abs(tail[i][k]-tail[0][k]) for i in [1,2] for k in ['x','y','z'])
checks={'terminal_position_velocity_acceleration_boundary':terminal_error<1e-6 and terminal_flat<1e-6,'native_action_and_landing':flight['result']=='PASS' and flight['action_success'] and flight['landed_and_disarmed'],'independent_goal_and_health':arrival['navigation_check_passed'],'boot_parameter_audit':boot['passed'],'isolated_mutable_state':not isolation['imported_parameter_or_mission_state'],'runtime_hashes_unchanged':not changed,'source_mutable_files_unchanged':not source_changed,'sampled_nominal_body_clearance_positive':clearance['sampled_envelope_margin_m']>0,'truth_samples_continuous_at_50hz':clearance['max_truth_sample_gap_sim_s']<=.025}
r={'scope':__doc__,'run_id':run.name,'passed':all(checks.values()),'checks':checks,'runtime_contract_sha256':contract['sha256'],'changed_runtime_files':changed,'changed_historical_source_mutable_files':source_changed,'independent_true_min_3d_error_m':arrival['minimum_true_3d_position_error_m'],'independent_true_goal_dwell_wall_s':arrival['max_contiguous_true_goal_dwell_wall_s'],'sampled_nominal_body_clearance_m':clearance['sampled_envelope_margin_m'],'last_spline_terminal_position_error_m':terminal_error,'last_spline_flat_tail_error_m':terminal_flat,'invalid_localization_after_enable':arrival['invalid_localization_samples_after_enable'],'map_or_navigation_failures':arrival['map_or_navigation_failure_lines_after_enable'],'evidence_sha256':{name:hashlib.sha256((run/name).read_bytes()).hexdigest() for name in ['flight.json','preflight.json','arrival-evaluation.json','crossing-evaluation.json','px4-boot-parameters.json','px4-run-isolation.json','runtime-contract.json']},'limitations':['Current room/route only; no multi-scene or real-flight qualification.','Nominal body-envelope distances are sampled; not formal continuous collision/uncertainty acceptance.']}
(run/'qualification.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r,indent=2));sys.exit(0 if r['passed'] else 1)
